(()=>{'use strict';const messages={event:'The event is reported by the client. The prepared description retains that attribution and line 14.',field:'Field meaning informs a candidate mapping. A reported key is not a current lookup, customer value or write permission.',amount:'The source supplies no amount. Preparation leaves it unresolved; the requirement and proposed test preserve the same absence.'};
function select(key){if(!messages[key])key='event';document.querySelectorAll('[data-trace]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.trace===key)));document.querySelectorAll('[data-trace-part]').forEach(el=>el.classList.toggle('trace-active',el.dataset.tracePart===key));document.querySelector('[data-trace-status]').textContent=messages[key];}
document.querySelectorAll('[data-trace]').forEach(b=>b.addEventListener('click',()=>{const u=new URL(location);u.searchParams.set('trace',b.dataset.trace);history.pushState({},'',u);select(b.dataset.trace);}));
function restore(){const u=new URL(location);select(u.searchParams.get('trace')||'event');const on=u.searchParams.get('context')!=='missing';document.querySelector('[data-context-toggle]').checked=on;document.body.classList.toggle('no-context',!on);}
document.querySelector('[data-context-toggle]').addEventListener('change',e=>{const u=new URL(location);if(e.target.checked)u.searchParams.delete('context');else u.searchParams.set('context','missing');history.pushState({},'',u);});window.addEventListener('popstate',restore);restore();})();
